    season_index,
    gladiator_id,
    name,
    rating,
    human_wins,
    human_losses,
    row_number() OVER (PARTITION BY league, season_index ORDER BY rating DESC, human_wins DESC, human_losses, gladiator_id) AS rank,
    (EXISTS ( SELECT 1
           FROM public.arena_standings h
          WHERE ((h.gladiator_id = s.gladiator_id) AND (h.season_index = s.season_index) AND (array_position(ARRAY['bronze'::text, 'silver'::text, 'gold'::text, 'champion'::text], h.league) > array_position(ARRAY['bronze'::text, 'silver'::text, 'gold'::text, 'champion'::text], s.league))))) AS promoted,
    (((human_wins + human_losses) >= 5) AND (NOT (EXISTS ( SELECT 1
           FROM public.arena_standings h
          WHERE ((h.gladiator_id = s.gladiator_id) AND (h.season_index = s.season_index) AND ((h.human_wins + h.human_losses) >= 5) AND (array_position(ARRAY['bronze'::text, 'silver'::text, 'gold'::text, 'champion'::text], h.league) > array_position(ARRAY['bronze'::text, 'silver'::text, 'gold'::text, 'champion'::text], s.league))))))) AS reward_eligible
   FROM public.arena_standings s;

